import { Alert, AlertTitle, Typography } from "@mui/material";
import type React from "react";

interface DeliveryPublishRefusedNoticeProps {
	/** What the source said, in its own words. */
	reason: string;
	/** What the connection calls this kind of source, e.g. "Jira Release". */
	sourceLabel: string;
	refusedOn: string | null;
	/** The tenant's own word for a Delivery - it may well be "Launch". */
	deliveryTerm: string;
}

export const PUBLISH_REFUSED_TITLE = "Forecast not published";

/**
 * Shown on a Delivery whose forecast the source refused to take. It exists because the alternative is
 * a switch that was turned on and appears to do nothing at all: the Release simply never changes, and
 * nothing anywhere says why.
 *
 * Deliberately milder than the source-unavailable notice beside it, and deliberately separate. That
 * one says the values on the row are frozen and nothing is maintaining them; this one says the
 * Delivery is perfectly healthy and one optional thing it was asked to do elsewhere did not happen.
 * Merging them would have a working Delivery read as a broken one.
 */
const DeliveryPublishRefusedNotice: React.FC<
	DeliveryPublishRefusedNoticeProps
> = ({ reason, sourceLabel, refusedOn, deliveryTerm }) => {
	const named = sourceLabel.trim();
	const target = named ? `the ${named}` : "the source this follows";

	return (
		<Alert severity="info" sx={{ borderRadius: 0 }}>
			<AlertTitle>{PUBLISH_REFUSED_TITLE}</AlertTitle>
			{`This forecast could not be written to ${target}${sinceWhen(refusedOn)}. Everything else about this ${deliveryTerm.toLowerCase()} is up to date.`}
			{/* The remote's own sentence, quoted rather than paraphrased: it names what to fix in the
			    words the reader will search for, and it is not ours to rewrite. */}
			<Typography
				variant="body2"
				component="p"
				// The remote chose these words, so they can contain anything - a url, an id, a stack
				// fragment with no space in it. The box around this clips rather than scrolls, and the
				// part that gets cut off is exactly the part naming what to fix.
				sx={{ mt: 1, fontStyle: "italic", overflowWrap: "anywhere" }}
			>
				{reason}
			</Typography>
		</Alert>
	);
};

/**
 * Read in UTC, because the day stored is the instance's day rather than this browser's. Read as a
 * local day it would name the day before west of UTC.
 */
function sinceWhen(refusedOn: string | null): string {
	if (refusedOn === null) {
		return "";
	}

	const day = new Date(refusedOn).toLocaleDateString(undefined, {
		timeZone: "UTC",
	});

	return `, last tried on ${day}`;
}

export default DeliveryPublishRefusedNotice;

import { render, screen } from "@testing-library/react";
import { describe, expect, it } from "vitest";
import DeliveryPublishRefusedNotice from "./DeliveryPublishRefusedNotice";

/**
 * The notice a Delivery shows when the source would not take its forecast. It exists because the
 * alternative is a switch somebody turned on that appears to do nothing at all: the Release simply
 * never changes, and nothing anywhere says why.
 *
 * What it has to get right is that this Delivery is fine. Everything on the row beside it is current;
 * one optional thing it does somewhere else did not happen.
 */

const A_JIRA_RELEASE = "Jira Release";
const WHAT_JIRA_SAID =
	"You must have global or project administrator rights in order to modify versions.";
const REFUSED_ON = "2026-08-25T00:00:00.000Z";

function renderNotice(
	overrides: Partial<
		React.ComponentProps<typeof DeliveryPublishRefusedNotice>
	> = {},
) {
	return render(
		<DeliveryPublishRefusedNotice
			reason={WHAT_JIRA_SAID}
			sourceLabel={A_JIRA_RELEASE}
			refusedOn={REFUSED_ON}
			deliveryTerm="Launch"
			{...overrides}
		/>,
	);
}

describe("DeliveryPublishRefusedNotice (US-06)", () => {
	it("says the forecast was not published", () => {
		renderNotice();

		expect(screen.getByText("Forecast not published")).toBeInTheDocument();
	});

	/**
	 * AC-06.1. Quoted rather than paraphrased: the remote's own sentence names what to fix in the
	 * words the reader will search for, and a Lighthouse rewording loses exactly that.
	 */
	it("quotes what the source said, word for word", () => {
		renderNotice();

		expect(screen.getByText(WHAT_JIRA_SAID)).toBeInTheDocument();
	});

	it("names the source the way the connection names it", () => {
		renderNotice({ sourceLabel: "Jira Fix Version" });

		expect(screen.getByText(/Jira Fix Version/)).toBeInTheDocument();
	});

	/**
	 * The label is what the connection calls this kind of source. The row above falls back to the
	 * stored key when the fetched list does not name it, so a blank arrives only when the Delivery has
	 * no key either - rare, and the sentence still has to read like one.
	 */
	it.each([
		["nothing at all", ""],
		["nothing but spaces", "   "],
	])("still reads as a sentence when the source is named %s", (_when, label) => {
		renderNotice({ sourceLabel: label });

		expect(
			screen.getByText(/could not be written to the source this follows/),
		).toBeInTheDocument();
	});

	// AC-06.1 again: an administrator has to know whether this is happening now or happened once,
	// months ago, before something else was fixed.
	it("says when it was last tried", () => {
		renderNotice();

		expect(screen.getByText(/last tried on/)).toBeInTheDocument();
	});

	/**
	 * The whole sentence, so the day clause cannot be swapped for something else that still matches a
	 * loose pattern. What the day itself renders as is not asserted here: the component reads it in the
	 * instance's zone rather than this browser's, and a test process cannot change its own timezone
	 * once Intl has initialised - so on a UTC host the two readings are the same characters and no
	 * assertion could tell them apart.
	 */
	it("says nothing more than that it was tried, and when", () => {
		renderNotice({ refusedOn: null });

		expect(
			screen.getByText(
				"This forecast could not be written to the Jira Release. Everything else about this launch is up to date.",
			),
		).toBeInTheDocument();
	});

	it("says nothing about a day nobody recorded", () => {
		renderNotice({ refusedOn: null });

		expect(screen.queryByText(/last tried on/)).not.toBeInTheDocument();
	});

	/**
	 * The half that stops this reading as a broken Delivery: everything on the row beside it was read
	 * from the source in the ordinary way and is current, because the refusal is about a write.
	 *
	 * A tenant who renamed Delivery to Launch must never be shown the word "delivery". The sibling
	 * notice sidesteps the problem by never using the word at all; this sentence needs it, so the term
	 * is passed in.
	 */
	it("says the rest of it is fine, in the tenant's own word", () => {
		renderNotice();

		expect(
			screen.getByText(/Everything else about this launch is up to date/),
		).toBeInTheDocument();
	});
});

import { render, screen } from "@testing-library/react";
import { MemoryRouter } from "react-router";
import { describe, expect, it, vi } from "vitest";
import { Delivery } from "../../../../../models/Delivery";
import type { IEntityReference } from "../../../../../models/EntityReference";
import { Feature } from "../../../../../models/Feature";
import type { IWorkItem } from "../../../../../models/WorkItem";
import { DeliverySelectionMode } from "../../../../../models/WorkItemRules";
import DeliverySection from "./DeliverySection";

/**
 * Where the refused-publish notice appears, and how it sits beside the broken-source one. The two are
 * separate on purpose and can both be true at once: one says nothing is maintaining the values on the
 * row, the other says the row is current and a write elsewhere did not happen. Collapsing them would
 * have a healthy Delivery read as a broken one.
 */

vi.mock("../../../../../services/TerminologyContext", () => ({
	useTerminology: () => ({ getTerm: (key: string) => key }),
}));

vi.mock("../../../../../services/Api/ApiServiceContext", () => ({
	ApiServiceContext: {
		_currentValue: { featureService: { getFeatureWorkItems: vi.fn() } },
	},
}));

vi.mock(
	"../../../../../components/Common/FeatureListDataGrid/FeatureProgressIndicator",
	() => ({
		default: ({ feature }: { feature: { id: number } }) => (
			<span data-testid={`progress-${feature.id}`} />
		),
	}),
);

vi.mock(
	"../../../../../components/Common/WorkItemsDialog/WorkItemsDialog",
	() => ({
		default: ({ open }: { items: IWorkItem[]; open: boolean }) =>
			open ? <div data-testid="work-items-dialog" /> : null,
	}),
);

const teams: IEntityReference[] = [{ id: 1, name: "Team Alpha" }];
const WHAT_JIRA_SAID =
	"You must have global or project administrator rights in order to modify versions.";

function aBroadcastingDelivery(overrides: Partial<Delivery> = {}): Delivery {
	const delivery = new Delivery();
	delivery.id = 1;
	delivery.name = "Release 3.0";
	delivery.date = "2026-12-19T00:00:00.000Z";
	delivery.features = [1];
	delivery.likelihoodPercentage = 72;
	delivery.teamsWithoutForecast = [];
	delivery.progress = 40;
	delivery.remainingWork = 6;
	delivery.totalWork = 10;
	delivery.hasSufficientData = true;
	delivery.completionDates = [];
	delivery.featureLikelihoods = [
		{ featureId: 1, likelihoodPercentage: 72, hasSufficientData: true },
	];
	delivery.selectionMode = DeliverySelectionMode.SourceBound;
	delivery.sourceKey = "jira-release";
	delivery.sourceReference = "10007";
	delivery.sourceLastSyncedOn = "2026-08-20T00:00:00.000Z";
	delivery.sourceUnavailableReason = null;
	delivery.publishForecastToSource = true;
	delivery.lastPublishRefusedOn = null;
	delivery.lastPublishRefusalReason = null;
	delivery.isOverdue = false;

	return Object.assign(delivery, overrides);
}

function featureNamed(id: number, name: string): Feature {
	const feature = new Feature();
	feature.id = id;
	feature.name = name;
	feature.remainingWork = { "1": 3 };
	feature.totalWork = { "1": 5 };
	feature.forecasts = [];

	return feature;
}

function renderSection(delivery: Delivery) {
	return render(
		<MemoryRouter>
			<DeliverySection
				delivery={delivery}
				features={[featureNamed(1, "Checkout")]}
				isExpanded={false}
				isLoadingFeatures={false}
				onToggleExpanded={vi.fn()}
				onDelete={vi.fn()}
				onEdit={vi.fn()}
				teams={teams}
				deliverySources={[{ key: "jira-release", displayName: "Jira Release" }]}
			/>
		</MemoryRouter>,
	);
}

describe("DeliverySection refused-publish notice (US-06)", () => {
	it("shows the notice on a Delivery whose forecast was refused", () => {
		renderSection(
			aBroadcastingDelivery({
				lastPublishRefusalReason: WHAT_JIRA_SAID,
				lastPublishRefusedOn: "2026-08-25T00:00:00.000Z",
			}),
		);

		expect(screen.getByText("Forecast not published")).toBeInTheDocument();
	});

	it("shows nothing on a Delivery nothing has refused", () => {
		renderSection(aBroadcastingDelivery());

		expect(
			screen.queryByText("Forecast not published"),
		).not.toBeInTheDocument();
	});

	/**
	 * AC-06.4, on screen. Reading Releases and writing to them are separate capabilities, so a refused
	 * write must not make a Delivery that is syncing perfectly well look like one whose source is gone.
	 */
	it("does not make a healthy source look broken", () => {
		renderSection(
			aBroadcastingDelivery({ lastPublishRefusalReason: WHAT_JIRA_SAID }),
		);

		expect(screen.queryByText("Source unavailable")).not.toBeInTheDocument();
	});

	/**
	 * A Delivery that follows nothing has no source to have refused it. Unreachable through the API -
	 * both ways of letting go clear the report - but a hand-edited row would otherwise be told its
	 * forecast could not be written to a source it does not have.
	 */
	it("says nothing on a Delivery that follows nothing at all", () => {
		renderSection(
			aBroadcastingDelivery({
				selectionMode: DeliverySelectionMode.Manual,
				lastPublishRefusalReason: WHAT_JIRA_SAID,
			}),
		);

		expect(
			screen.queryByText("Forecast not published"),
		).not.toBeInTheDocument();
	});

	/**
	 * The backend clears the report when the Release turns out to be gone, so the two should never both
	 * arrive. If one ever did, the component is not the place to hide it - it renders what it is given,
	 * and each notice sends the reader somewhere different.
	 */
	it("renders both if it is somehow handed both", () => {
		renderSection(
			aBroadcastingDelivery({
				sourceUnavailableReason: "SourceNotFound",
				lastPublishRefusalReason: WHAT_JIRA_SAID,
			}),
		);

		expect(screen.getByText("Source unavailable")).toBeInTheDocument();
		expect(screen.getByText("Forecast not published")).toBeInTheDocument();
	});

	it("keeps the Delivery's own values on screen beside the notice", () => {
		renderSection(
			aBroadcastingDelivery({ lastPublishRefusalReason: WHAT_JIRA_SAID }),
		);

		expect(screen.getByText("Release 3.0")).toBeInTheDocument();
	});
});
